xpath.script:

document.addEventListener("DOMContentLoaded", function () {
    var auctionBtn = document.getElementById("auction-btn");
    var urlParams = new URLSearchParams(window.location.search);
    var isAuctionActive = urlParams.get("auction") === "true";

    // If auction filter is active, update button appearance
    if (isAuctionActive) {
        auctionBtn.classList.remove("btn-outline-primary");
        auctionBtn.classList.add("btn-secondary-outline-primary");
        auctionBtn.textContent = "Showing Auctions";
    }

    // Button click event
    auctionBtn.addEventListener("click", function () {
        var url = new URL(window.location.href);
        if (isAuctionActive) {
            url.searchParams.delete("auction"); // Remove auction filter
        } else {
            url.searchParams.set("auction", "true"); // Apply auction filter
        }
        window.location.href = url.toString();
    });
});
